import Foundation

/// Operator precedence and keyword classes, read from SQLite's sources (`src/parse.y` and
/// `tool/mkkeywordhash.c`) for a default build, and rendered as Swift shared by SQLiteSyntax
/// (printing, name quoting) and SQLiteParser (parsing).
public enum SQLiteSourceTables {

    /// First line of the generated file (distinct from `SyntaxGenerator.header`, so regenerating the
    /// syntax types without the SQLite sources leaves this file alone).
    public static let header = "// Generated by sqlite-grammar from SQLite's src/parse.y and tool/mkkeywordhash.c. Do not edit."

    public struct Error: Swift.Error, CustomStringConvertible {
        public var description: String
    }

    /// parse.y precedence lines, named by their first token.
    static let precedenceNames: [String: String] = [
        "OR": "or", "AND": "and", "NOT": "not", "IS": "equality", "GT": "comparison", "ESCAPE": "escape",
        "BITAND": "bitwise", "PLUS": "additive", "STAR": "multiplicative", "CONCAT": "concatenation",
        "COLLATE": "collate", "BITNOT": "unary",
    ]

    public static func swiftSource(parseY: String, keywordHash: String) throws(Error) -> String {
        // Precedence: `%left OR.` … in order, weakest first.
        var levels: [(name: String, tokens: [String])] = []
        for line in parseY.split(separator: "\n") {
            let parts = line.split(separator: " ", omittingEmptySubsequences: true)
            guard let directive = parts.first, ["%left", "%right", "%nonassoc"].contains(directive), parts.count > 1 else { continue }
            let tokens = parts.dropFirst().map { $0.trimmingCharacters(in: CharacterSet(charactersIn: ".")) }
            guard let name = precedenceNames[tokens[0]] else {
                if tokens == ["ON"] { continue }   // join constraint precedence: not an expression operator
                throw Error(description: "parse.y: unknown precedence line \(line); update SQLiteSourceTables.precedenceNames")
            }
            levels.append((name, tokens))
        }
        guard levels.count == precedenceNames.count else { throw Error(description: "parse.y: expected \(precedenceNames.count) precedence levels, found \(levels.count)") }

        // Keywords: { "NAME", "TK_TOKEN", MASK, PRIORITY } in mkkeywordhash.c, minus features off by default.
        let regex = try! NSRegularExpression(pattern: #"\{\s*"([A-Z_]+)",\s*"TK_([A-Z_]+)",\s*([A-Z|]+)"#)
        var keywords: [(name: String, token: String)] = []
        for m in regex.matches(in: keywordHash, range: NSRange(keywordHash.startIndex..., in: keywordHash)) {
            let get = { (i: Int) in String(keywordHash[Range(m.range(at: i), in: keywordHash)!]) }
            if get(3) == "ORDERSET" { continue }   // SQLITE_ENABLE_ORDERED_SET_AGGREGATES is off by default
            keywords.append((get(1), get(2)))
        }
        guard keywords.count > 100 else { throw Error(description: "mkkeywordhash.c: keyword table not found") }

        // `%fallback ID …  .` with %ifdef/%ifndef sections evaluated for a default build.
        guard let start = parseY.range(of: "%fallback ID") else { throw Error(description: "parse.y: %fallback ID not found") }
        var fallbackTokens: Set<String> = []
        var active: [Bool] = []
        for line in parseY[start.upperBound...].split(separator: "\n") {
            let t = line.trimmingCharacters(in: .whitespaces)
            if t == "." { break }
            if t.hasPrefix("%ifdef ") || t.hasPrefix("%ifndef ") {
                let defined = false   // default build: no SQLITE_OMIT_* or SQLITE_ENABLE_* options
                active.append(t.hasPrefix("%ifdef ") ? defined : !defined)
                continue
            }
            if t.hasPrefix("%endif") { _ = active.popLast(); continue }
            guard active.allSatisfy({ $0 }) else { continue }
            for token in t.split(separator: " ") { fallbackTokens.insert(token.trimmingCharacters(in: CharacterSet(charactersIn: "."))) }
        }

        func set(_ names: [String]) -> String {
            "[" + names.sorted().map { "\"\($0)\"" }.joined(separator: ", ") + "]"
        }
        let all = keywords.map(\.name)
        let fallback = keywords.filter { fallbackTokens.contains($0.token) }.map(\.name)
        let tokenKeywords = { (token: String) in keywords.filter { $0.token == token }.map(\.name) }

        var out = "\(header)\n\n"
        out += "/// Operator binding strengths from parse.y (`%left OR.` … `%right BITNOT.`), weakest first.\n"
        out += "package enum ExpressionPrecedence {\n"
        for (i, level) in levels.enumerated() {
            out += "    /// \(level.tokens.joined(separator: " "))\n"
            out += "    package static let \(level.name) = \(i + 1)\n"
        }
        out += "    /// Literals, names, function calls, parenthesized and bracketed forms.\n"
        out += "    package static let atom = \(levels.count + 1)\n}\n\n"
        out += "/// SQLite's keyword classes (mkkeywordhash.c, parse.y `%fallback ID`), for a default build.\n"
        out += "package enum SQLiteKeywords {\n"
        out += "    /// Every keyword.\n    package static let all: Set<String> = \(set(all))\n\n"
        out += "    /// Keywords that become identifiers where the keyword itself cannot appear (`%fallback ID`).\n"
        out += "    package static let fallbackToIdentifier: Set<String> = \(set(fallback))\n\n"
        out += "    /// `JOIN_KW`\n    package static let joinKeywords: Set<String> = \(set(tokenKeywords("JOIN_KW")))\n\n"
        out += "    /// `LIKE_KW`\n    package static let likeKeywords: Set<String> = \(set(tokenKeywords("LIKE_KW")))\n\n"
        out += "    /// `CTIME_KW`\n    package static let timeLiterals: Set<String> = \(set(tokenKeywords("CTIME_KW")))\n}\n"
        return out
    }
}
